static void Line(Transform r,string n,Vector2 a,Vector2 b,float width,float y,Material m){var d=b-a;Quad(r,n,(a.x+b.x)/2,(a.y+b.y)/2,width,d.magnitude,y,m,Mathf.Atan2(d.x,d.y)*Mathf.Rad2Deg);}
static void Puddle(Transform r,float x,float z,float radius,Material m){int count=12;var v=new Vector3[count+1];var uv=new Vector2[count+1];var t=new int[count*3];for(int i=0;i<count;i++){float a=i*Mathf.PI*2/count;float rad=radius*R(.6f,1.15f);v[i+1]=new Vector3(Mathf.Cos(a)*rad,0,Mathf.Sin(a)*rad*.55f);uv[i+1]=new Vector2(v[i+1].x,v[i+1].z);t[i*3]=0;t[i*3+1]=(i+1)%count+1;t[i*3+2]=i+1;}var mesh=new Mesh();mesh.vertices=v;mesh.uv=uv;mesh.triangles=t;mesh.RecalculateNormals();mesh.RecalculateBounds();temporary.Add(mesh);var g=new GameObject("ShallowRainPuddle",typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(r,false);g.transform.localPosition=new Vector3(x,.021f,z);g.GetComponent<MeshFilter>().sharedMesh=mesh;g.GetComponent<Renderer>().sharedMaterial=m;parts.Add(g);}
static int Bake(Transform r,string name,Material[] mats){var combines=new List<CombineInstance>();var used=new List<Material>();var temps=new List<Mesh>();foreach(var mat in mats){var list=new List<CombineInstance>();foreach(var g in parts)if(g.GetComponent<Renderer>().sharedMaterial==mat)list.Add(new CombineInstance{mesh=g.GetComponent<MeshFilter>().sharedMesh,transform=g.transform.localToWorldMatrix});if(list.Count==0)continue;var part=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};part.CombineMeshes(list.ToArray(),true,true);temps.Add(part);combines.Add(new CombineInstance{mesh=part,transform=Matrix4x4.identity});used.Add(mat);}var mesh=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(combines.ToArray(),false,true);mesh.RecalculateBounds();string path=Root+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mesh=old;mesh.UploadMeshData(false);}else AssetDatabase.CreateAsset(mesh,path);var child=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));child.transform.SetParent(r,false);child.GetComponent<MeshFilter>().sharedMesh=mesh;child.GetComponent<Renderer>().sharedMaterials=used.ToArray();foreach(var g in parts)Object.DestroyImmediate(g);parts.Clear();foreach(var m in temporary)Object.DestroyImmediate(m);temporary.Clear();foreach(var m in temps)Object.DestroyImmediate(m);return mesh.triangles.Length/3;}
static Texture2D Concrete(){var t=new Texture2D(512,512,TextureFormat.RGB24,false);for(int y=0;y<512;y++)for(int x=0;x<512;x++){float broad=Mathf.PerlinNoise(x*.028f,y*.028f);float noise=(float)rng.NextDouble();float c=.64f+broad*.16f+noise*.10f;if(noise<.035f)c-=.12f;t.SetPixel(x,y,new Color(c,c,c*.98f));}t.Apply();string path=Root+"/ConcreteGrain.png";File.WriteAllBytes(path,t.EncodeToPNG());Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.wrapMode=TextureWrapMode.Repeat;imp.anisoLevel=8;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
