for(int i=0;i<18;i++){float z=-315+i*36;Line(r,"LoadingBay",new Vector2(-220,z),new Vector2(-245,z),.12f,.025f,yellow);Line(r,"LoadingBay",new Vector2(-220,z),new Vector2(-220,z+20),.12f,.025f,yellow);}
