if(i%2==0){Box(r,"BollardBase",new Vector3(109.3f,.13f,z),new Vector3(1.1f,.26f,1),dark);Box(r,"BollardStem",new Vector3(109.3f,.55f,z),new Vector3(.45f,.65f,.45f),dark);Box(r,"BollardHead",new Vector3(109.3f,.88f,z),new Vector3(.9f,.2f,.5f),dark);Box(r,"RubberFender",new Vector3(113.5f,-1.6f,z),new Vector3(.55f,2.4f,.85f),dark);}Box(r,"DrainGrate",new Vector3(106,.025f,z),new Vector3(.55f,.035f,1.2f),dark);for(int k=0;k<6;k++)Box(r,"GrateBar",new Vector3(106,.05f,z-.5f+k*.2f),new Vector3(.5f,.015f,.035f),cap);}
